/** Verification is separately bounded from construction and the one raw
 * search. These are conservative per-phase envelopes, not exact visit counts.
 * Compile includes the original model/snapshot and stays inside the kernel's
 * single 30s interval. No phase can be restarted or have its reservation refunded. */
export function icePhaseQuotes(recipe){const B=recipe.bodyCount,A=recipe.source?.width*recipe.source?.height||16;integer(B,1,23);integer(A,1,100);const S=6,G=8,J=3,V=64*(1+A+B*S+G*(A+4*J+1)+B+G+4*S),D=151,P=1024;return{
 'static-audit':{worlds:16,transitions:3*V+8*(16*A*A+32*A+21*B*(S*S+4*S+1)+B*G*S+B*B+G*G+1000),micro:5*B+A,maxMilliseconds:30000},
 'spatial-compile':{worlds:16,transitions:2*V+64*(A+B*B+B*G+B*S)+B*A*(16*S+4*(8*S+G*(2*S+3))+8),micro:B*A+3*B,maxMilliseconds:30000},
 'joint-search':{worlds:10000,transitions:JOINT_BUDGET.maxTransitions,micro:JOINT_BUDGET.maxMicroStates,maxMilliseconds:30000},
 'dual-replay':{worlds:8+24*D+6*P+12*B,transitions:8+24*D+6*P+12*B,micro:2+2*P+2*D,maxMilliseconds:30000}};}
export function createIcePhaseAccount(recipe,{qualificationOnly=false,now=Date.now}={}){if(!qualificationOnly)assert.equal(now,Date.now);const quotes=icePhaseQuotes(recipe),rows={},order=[],start=now();let previous=start;const time=()=>{const t=now();integer(t);assert(t>=previous);previous=t;return t;};return{
 begin(name){assert(quotes[name]&&!rows[name]);assert(time()-start<90000,'Combined verification deadline');const t=time();rows[name]={name,status:'RUNNING',startedAt:t,endedAt:null,elapsedMilliseconds:0,reservation:quotes[name],exactWorldVisitsClaimed:false};order.push(name);},
 guard(name){const r=rows[name];assert(r?.status==='RUNNING');assert(time()-r.startedAt<r.reservation.maxMilliseconds,'phase-deadline:'+name);assert(time()-start<90000,'Combined verification deadline');},
 finish(name,error=null){const r=rows[name];assert(r?.status==='RUNNING');const t=time();r.endedAt=t;r.elapsedMilliseconds=t-r.startedAt;r.reason=error?String(error):null;r.status=error?'TERMINAL':'COMPLETED';if(r.elapsedMilliseconds>=r.reservation.maxMilliseconds||t-start>=90000){r.status='TERMINAL';r.reason='phase-deadline:'+name;throw Error(r.reason);}},
 report(){return structuredClone({version:'ice-supply-separated-verification-v1',qualificationOnly,quotes,order,phases:rows,exactWorldVisitsClaimed:false,globalVerificationMilliseconds:90000,searchGuardIncluded:true,compilationSharesKernelInterval:true});}};}
export function assertIcePhases(a,recipe,{qualificationOnly=false}={}){assert.equal(a.version,'ice-supply-separated-verification-v1');assert.equal(a.qualificationOnly,qualificationOnly);assert.deepEqual(a.quotes,icePhaseQuotes(recipe));assert.equal(a.exactWorldVisitsClaimed,false);assert.equal(a.globalVerificationMilliseconds,90000);assert(a.searchGuardIncluded&&a.compilationSharesKernelInterval);assert.deepEqual(a.order,['static-audit','spatial-compile','joint-search','dual-replay'].slice(0,a.order.length));assert.deepEqual(Object.keys(a.phases),a.order);for(const name of a.order){const q=a.phases[name];assert.equal(q.name,name);assert.deepEqual(q.reservation,a.quotes[name]);integer(q.startedAt);integer(q.endedAt,q.startedAt);assert.equal(q.elapsedMilliseconds,q.endedAt-q.startedAt);assert(['COMPLETED','TERMINAL'].includes(q.status));assert.equal(q.exactWorldVisitsClaimed,false);if(q.status==='COMPLETED'){assert.equal(q.reason,null);assert(q.elapsedMilliseconds<q.reservation.maxMilliseconds);}else assert(typeof q.reason==='string'&&q.reason);}return true;}
