export function finalizeIceAcceptanceMetadata(q){q.mathematicalEvidenceValidated=q.joint?.accepted===true;q.derivedCertificate=q.joint?.derivedCertificate??null;if(!q.accepted){q.L=null;q.admissionBand=null;}q.redesignRequired=!q.accepted;return q;}
export async function discoverRetainedPublicFiles(candidates,mathPaths,allowed,has=exists){try{for(const q of candidates)if(q.attempt)for(const f of publicFiles(q))if(await has(f)){if(!mathPaths.includes(f))mathPaths.push(f);if(!allowed.includes(f))allowed.push(f);}return null;}catch(e){return e.message;}}

