 return{status:complete?'COMPLETE':'INTERRUPTED',restartAllowed:false,maximumInputs:recipes.length,consumedInputs:started,savedReceiptCount:savedIndices.length,missingReceiptRecipeIndices:Array.from({length:started},(_,i)=>i).filter(i=>!savedIndices.includes(i)),unexecutedRecipes:recipes.slice(started).map((r,i)=>({recipeIndex:started+i,recipeId:r.recipeId,sourceLevelId:r.sourceLevelId})),finalizationError:finalizationError??(complete?null:'Batch ended without all declared inputs'),normalActualAuditAllowed:complete};
