 assert.deepEqual(q.author,CHECKPOINT06_AUTHOR);assert.deepEqual(q.reviewer,CHECKPOINT06_REVIEWER);assert.deepEqual(q.adapterQualification,HISTORY_ADAPTER_QUALIFICATION);assert.deepEqual(q.originalCheckpointDescriptorOnly,ORIGINAL_CHECKPOINT05);assert.deepEqual(q.originalReview,ORIGINAL_CHECKPOINT05_REVIEW);
 for(const d of [CHECKPOINT06_AUTHOR,CHECKPOINT06_REVIEWER])assert.equal(q.toolBindings[d.path],d.sha256);
 for(const k of ['newRealHistoryLoads','newRealHistoryMerges','newRealHistoryExports','newCheckpointReseals','newModelCalls','newConstructions','newSearches','newReplayCalls','newLedgerClaims','publicClaimsStarted'])assert.equal(q[k],0);
 assert.equal(q.oldFilesChanged,false);return true;
