   for(const[kind,od]of [['construction',subject.constructionOwner],['mathematical',subject.mathOwner]]){const o=await r.bound(od),expected=kind==='construction'?[...constructionFiles(pd,p),directory+'/execution-start.json',...candidates.filter(q=>q.constructionEvidence).map(q=>q.constructionEvidence.path)]:[...subject.receipts.map(x=>x.path),...candidates.flatMap(publicFiles)],attemptIds=kind==='mathematical'?candidates.filter(q=>q.attempt).map(q=>q.attempt.id):[];assertWholeBoardOwner(o,{kind,plan:pd,experimentId:p.experimentId,namespace:compileCanonicalHistoryPath(x.h.bundle.scope).canonical(path.resolve(kind==='construction'?LATE_PREFIX_CONSTRUCTION_LEDGER:PUBLIC_LEDGER)),attemptIds,files:expected});for(const f of o.files){assert.equal(sha(await r.bytes(f.path)),f.sha256);allowed.push(f.path);}if(kind==='construction'){assert.equal(o.closedCampaigns.length,1);const c=o.closedCampaigns[0],raw=await r.bound(c.descriptor);assertWholeBoardClosedCampaign(c,raw,{plan:pd,experimentId:p.experimentId,maximumInputs:p.maximumInputs,receipts:subject.receipts,formedWorldFiles:formed});}else assert.deepEqual(o.closedCampaigns,[]);}
